import { z } from "zod";
import { DateTimeSchema, RefSchema, UlidSchema } from "./common.js";

/**
 * ULID schema for meta items - uses the same strict validation as core items.
 * All ULIDs must be exactly 26 characters in Crockford base32 format.
 */
const MetaUlidSchema = UlidSchema;

/**
 * Agent session protocol - commands to run at session lifecycle events
 */
export const SessionProtocolSchema = z.object({
  start: z.string().nullable().optional(),
  checkpoint: z.string().nullable().optional(),
  end: z.string().nullable().optional(),
});

/**
 * Agent dispatch event types - lifecycle events that can trigger agent spawning
 * AC: @agent-definition-schema ac-2
 */
export const AgentDispatchEventSchema = z.enum([
  "task.in_progress",
  "task.ready",
  "task.needs_work",
  "task.pending_review",
]);

/**
 * Agent dispatch filter - constraints for matching tasks during dispatch
 * AC: @agent-definition-schema ac-3
 */
export const AgentDispatchFilterSchema = z.object({
  automation: z.enum(["eligible", "ineligible"]).optional(),
  tags: z.array(z.string()).optional(),
  priority: z.number().optional(),
});

/**
 * Agent dispatch rule - maps an event type to optional filters
 * AC: @agent-definition-schema ac-2
 */
export const AgentDispatchRuleSchema = z.object({
  on: AgentDispatchEventSchema,
  filter: AgentDispatchFilterSchema.optional(),
});

/**
 * Agent budget settings - limits on task count and time
 * AC: @agent-definition-schema ac-4
 */
export const AgentBudgetSchema = z.object({
  max_tasks: z.number().positive().optional(),
  max_retries: z.number().int().nonnegative().optional(),
  timeout_minutes: z.number().positive().optional(),
});

/**
 * Agent concurrency settings
 * AC: @agent-definition-schema ac-6
 */
export const AgentConcurrencySchema = z.object({
  max_concurrent: z.number().int().positive().default(1),
});

/**
 * Agent definition - describes an agent's role and capabilities
 * AC: @agent-definition-schema ac-1 through ac-8
 */
export const AgentSchema = z.object({
  _ulid: MetaUlidSchema,
  id: z.string().min(1, "Agent ID is required"),
  name: z.string().min(1, "Agent name is required"),
  description: z.string().optional(),
  capabilities: z.array(z.string()).default([]),
  tools: z.array(z.string()).default([]),
  session_protocol: SessionProtocolSchema.optional(),
  conventions: z.array(z.string()).default([]),
  // New dispatch/runtime fields (AC: @agent-definition-schema ac-1 through ac-8)
  adapter: z.string().optional(),
  dispatch: z.array(AgentDispatchRuleSchema).default([]),
  skills: z.array(z.string()).default([]),
  budget: AgentBudgetSchema.optional(),
  concurrency: AgentConcurrencySchema.default({ max_concurrent: 1 }),
  auto_approve: z.boolean().default(false),
  prompt_template: z.string().optional(),
  /** Automation eligibility for agent list filtering (eligible|ineligible) */
  automation: z.enum(["eligible", "ineligible"]).optional(),
  /** Tags for filtering and categorization */
  tags: z.array(z.string()).default([]).optional(),
});

/**
 * Workflow step types
 */
export const WorkflowStepTypeSchema = z.enum(["check", "action", "decision"]);

/**
 * Workflow step execution hints
 */
export const StepExecutionSchema = z.object({
  mode: z.enum(["prompt", "silent", "skip"]).default("prompt"),
  timeout: z.number().nullable().optional(),
});

/**
 * Workflow step input definition
 */
export const StepInputSchema = z.object({
  name: z.string().min(1, "Input name is required"),
  description: z.string().optional(),
  required: z.boolean().default(true).optional(),
  type: z.enum(["string", "ref", "number"]).default("string").optional(),
});

/**
 * Workflow step - a single step in a workflow
 */
export const WorkflowStepSchema = z.object({
  type: WorkflowStepTypeSchema,
  content: z.string(),
  on_fail: z.string().optional(),
  options: z.array(z.string()).optional(), // For decision type
  execution: StepExecutionSchema.optional(),
  entry_criteria: z.array(z.string()).optional(),
  exit_criteria: z.array(z.string()).optional(),
  inputs: z.array(StepInputSchema).optional(),
});

/**
 * Workflow mode - interactive (default) for human-in-loop, loop for autonomous agents
 */
export const WorkflowModeSchema = z.enum(["interactive", "loop"]);

/**
 * Workflow definition - structured process definition
 */
export const WorkflowSchema = z.object({
  _ulid: MetaUlidSchema,
  id: z.string().min(1, "Workflow ID is required"),
  trigger: z.string().min(1, "Workflow trigger is required"),
  description: z.string().optional(),
  steps: z.array(WorkflowStepSchema).default([]),
  enforcement: z.enum(["advisory", "strict"]).default("advisory").optional(),
  mode: WorkflowModeSchema.default("interactive").optional(),
  based_on: RefSchema.optional(),
  tags: z.array(z.string()).default([]).optional(),
});

/**
 * Convention example (good/bad)
 */
export const ConventionExampleSchema = z.object({
  good: z.string(),
  bad: z.string(),
});

/**
 * Convention validation configuration
 */
export const ConventionValidationSchema = z.object({
  type: z.enum(["regex", "enum", "range", "prose"]),
  // For regex
  pattern: z.string().optional(),
  message: z.string().optional(),
  // For enum
  allowed: z.array(z.string()).optional(),
  // For range
  min: z.number().optional(),
  max: z.number().optional(),
  unit: z.enum(["words", "chars", "lines"]).optional(),
});

/**
 * Convention definition - project-specific rules and standards
 */
export const ConventionSchema = z.object({
  _ulid: MetaUlidSchema,
  domain: z.string().min(1, "Convention domain is required"),
  rules: z.array(z.string()).default([]),
  examples: z.array(ConventionExampleSchema).default([]),
  validation: ConventionValidationSchema.optional(),
});

/**
 * Observation types
 */
export const ObservationTypeSchema = z.enum([
  "friction",
  "success",
  "question",
  "idea",
]);

/**
 * Observation - feedback about workflows and conventions
 */
export const ObservationSchema = z.object({
  _ulid: MetaUlidSchema,
  type: ObservationTypeSchema,
  workflow_ref: RefSchema.optional(),
  content: z.string().min(1, "Observation content is required"),
  created_at: DateTimeSchema,
  author: z.string().optional(),
  resolved: z.boolean().default(false),
  resolution: z.string().nullable().optional(),
  resolved_at: DateTimeSchema.optional(),
  resolved_by: z.string().optional(),
  promoted_to: RefSchema.optional(),
});

/**
 * Skill origin - where the skill comes from
 */
export const SkillOriginSchema = z.enum(["core", "project", "local"]);

/**
 * Claude Code platform config - settings specific to Claude Code
 */
export const ClaudeCodeConfigSchema = z
  .object({
    disable_model_invocation: z.boolean().optional(),
    user_invocable: z.boolean().optional(),
    context: z.string().optional(),
    agent: z.string().optional(),
    model: z.string().optional(),
    argument_hint: z.string().optional(),
  })
  .strict();

/**
 * Codex platform config - settings specific to OpenAI Codex CLI
 */
export const CodexConfigSchema = z
  .object({
    allow_implicit_invocation: z.boolean().optional(),
    display_name: z.string().optional(),
    short_description: z.string().optional(),
    icon_small: z.string().optional(),
    icon_large: z.string().optional(),
    brand_color: z.string().optional(),
    default_prompt: z.string().optional(),
  })
  .strict();

/**
 * Platform config - container for platform-specific settings
 * Uses passthrough for unknown platforms to support future extensibility
 */
export const PlatformConfigSchema = z
  .object({
    claude_code: ClaudeCodeConfigSchema.optional(),
    codex: CodexConfigSchema.optional(),
  })
  .passthrough();

/**
 * Kebab-case regex for skill IDs - lowercase letters, numbers, and hyphens only
 * Must start with a letter and not end with a hyphen
 */
const KEBAB_CASE_REGEX = /^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$/;

/**
 * Skill definition - reusable agent capabilities stored in files
 * Content is stored in .kspec/skills/<id>/SKILL.md
 *
 * Extended with portable Agent Skills fields for multi-platform support:
 * - license, compatibility, allowed_tools for portability
 * - metadata for arbitrary key-value pairs
 * - platform_config for platform-specific settings
 */
export const SkillSchema = z.object({
  _ulid: MetaUlidSchema,
  _type: z.literal("skill").default("skill"),
  id: z
    .string({ required_error: "Skill ID is required" })
    .regex(
      KEBAB_CASE_REGEX,
      "Skill ID must be in kebab-case format (lowercase letters, numbers, and hyphens)",
    ),
  name: z.string().min(1, "Skill name is required"),
  description: z.string().optional(),
  origin: SkillOriginSchema,
  version: z.string().optional(),
  platforms: z.array(z.string()).default(["claude-code"]),
  depends_on: z.array(RefSchema).default([]),
  tags: z.array(z.string()).default([]),
  // Portable Agent Skills fields
  license: z.string().optional(),
  compatibility: z.string().optional(),
  allowed_tools: z.array(z.string()).default([]),
  metadata: z.record(z.string(), z.unknown()).optional(),
  platform_config: PlatformConfigSchema.optional(),
});

/**
 * Session context schema - ephemeral session state
 */
export const SessionContextSchema = z.object({
  focus: z.string().nullable(),
  threads: z.array(z.string()).default([]),
  open_questions: z.array(z.string()).default([]),
  updated_at: DateTimeSchema,
});

/**
 * Step result status
 */
export const StepResultStatusSchema = z.enum([
  "completed",
  "skipped",
  "failed",
]);

/**
 * Step result schema - result of executing a workflow step
 */
export const StepResultSchema = z.object({
  step_index: z.number(),
  status: StepResultStatusSchema,
  started_at: DateTimeSchema,
  completed_at: DateTimeSchema,
  entry_confirmed: z.boolean().optional(),
  exit_confirmed: z.boolean().optional(),
  notes: z.string().optional(),
  inputs: z.record(z.string()).optional(),
});

/**
 * Workflow run status
 */
export const WorkflowRunStatusSchema = z.enum([
  "active",
  "paused",
  "completed",
  "aborted",
]);

/**
 * Workflow run result - distinguishes between different completion types
 */
export const WorkflowRunResultSchema = z.enum([
  "success", // Normal completion through all steps
  "no_work_available", // Graceful exit - no eligible work to process
  "early_exit", // Intentional exit before all steps (not an error)
]);

/**
 * Workflow run schema - tracks execution of a workflow
 */
export const WorkflowRunSchema = z.object({
  _ulid: UlidSchema,
  workflow_ref: RefSchema,
  status: WorkflowRunStatusSchema,
  current_step: z.number(),
  total_steps: z.number(),
  started_at: DateTimeSchema,
  paused_at: DateTimeSchema.optional(),
  completed_at: DateTimeSchema.optional(),
  step_results: z.array(StepResultSchema).default([]),
  initiated_by: z.string().optional(),
  abort_reason: z.string().optional(),
  task_ref: RefSchema.optional(),
  result: WorkflowRunResultSchema.optional(), // Only set for completed runs
});

/**
 * Workflow runs file schema - container for all workflow runs
 */
export const WorkflowRunsFileSchema = z.object({
  kynetic_runs: z.string().default("1.0"),
  runs: z.array(WorkflowRunSchema).default([]),
});

/**
 * Meta manifest schema - the root structure for kynetic.meta.yaml
 */
export const MetaManifestSchema = z.object({
  kynetic_meta: z.string().default("1.0"),
  agents: z.array(AgentSchema).default([]),
  workflows: z.array(WorkflowSchema).default([]),
  conventions: z.array(ConventionSchema).default([]),
  observations: z.array(ObservationSchema).default([]),
  skills: z.array(SkillSchema).default([]),
  includes: z.array(z.string()).default([]),
});

// Type exports
export type SessionProtocol = z.infer<typeof SessionProtocolSchema>;
export type AgentDispatchEvent = z.infer<typeof AgentDispatchEventSchema>;
export type AgentDispatchFilter = z.infer<typeof AgentDispatchFilterSchema>;
export type AgentDispatchRule = z.infer<typeof AgentDispatchRuleSchema>;
export type AgentBudget = z.infer<typeof AgentBudgetSchema>;
export type AgentConcurrency = z.infer<typeof AgentConcurrencySchema>;
export type Agent = z.infer<typeof AgentSchema>;
export type WorkflowStepType = z.infer<typeof WorkflowStepTypeSchema>;
export type StepExecution = z.infer<typeof StepExecutionSchema>;
export type StepInput = z.infer<typeof StepInputSchema>;
export type WorkflowStep = z.infer<typeof WorkflowStepSchema>;
export type WorkflowMode = z.infer<typeof WorkflowModeSchema>;
export type Workflow = z.infer<typeof WorkflowSchema>;
export type ConventionExample = z.infer<typeof ConventionExampleSchema>;
export type ConventionValidation = z.infer<typeof ConventionValidationSchema>;
export type Convention = z.infer<typeof ConventionSchema>;
export type ObservationType = z.infer<typeof ObservationTypeSchema>;
export type Observation = z.infer<typeof ObservationSchema>;
export type SkillOrigin = z.infer<typeof SkillOriginSchema>;
export type ClaudeCodeConfig = z.infer<typeof ClaudeCodeConfigSchema>;
export type CodexConfig = z.infer<typeof CodexConfigSchema>;
export type PlatformConfig = z.infer<typeof PlatformConfigSchema>;
export type Skill = z.infer<typeof SkillSchema>;
export type SessionContext = z.infer<typeof SessionContextSchema>;
export type MetaManifest = z.infer<typeof MetaManifestSchema>;
export type StepResultStatus = z.infer<typeof StepResultStatusSchema>;
export type StepResult = z.infer<typeof StepResultSchema>;
export type WorkflowRunStatus = z.infer<typeof WorkflowRunStatusSchema>;
export type WorkflowRunResult = z.infer<typeof WorkflowRunResultSchema>;
export type WorkflowRun = z.infer<typeof WorkflowRunSchema>;
export type WorkflowRunsFile = z.infer<typeof WorkflowRunsFileSchema>;

/**
 * Meta item type - union of all meta item types
 */
export type MetaItem = Agent | Workflow | Convention | Observation | Skill;

/**
 * Type guard for skill items
 * Uses _type discriminant field for reliable discrimination
 */
export function isSkill(item: MetaItem | unknown): item is Skill {
  return (
    typeof item === "object" &&
    item !== null &&
    "_type" in item &&
    (item as { _type: unknown })._type === "skill"
  );
}

/**
 * Determine the type of a meta item
 * AC: @skill-meta-type ac-7 - skills discriminated by _type field
 */
export function getMetaItemType(
  item: MetaItem,
): "agent" | "workflow" | "convention" | "observation" | "skill" {
  if (isSkill(item)) return "skill";
  if ("capabilities" in item) return "agent";
  if ("trigger" in item) return "workflow";
  if ("domain" in item) return "convention";
  return "observation";
}

/**
 * Enhanced setup command for kspec agent integration.
 *
 * Orchestrates the full onboarding pipeline:
 * - Detect agent environment (Claude Code, Cline, etc.)
 * - Install hooks (UserPromptSubmit, Stop, PreToolUse guards)
 * - Render skills from .kspec/skills/ to .claude/skills/
 * - Generate kspec-agents.md
 *
 * AC: @enhanced-setup ac-1 - summary displayed listing each step performed
 * AC: @enhanced-setup ac-2 - all hook entries (UserPromptSubmit, Stop, PreToolUse) present
 * AC: @enhanced-setup ac-3 - rendered skill files exist for each skill targeting claude-code
 * AC: @enhanced-setup ac-4 - kspec-agents.md exists after setup
 * AC: @enhanced-setup ac-5 - --skip-skills flag skips skill rendering
 * AC: @enhanced-setup ac-6 - --dry-run displays planned actions without changes
 * AC: @enhanced-setup ac-7 - --status reports current state including agent detected
 * AC: @enhanced-setup ac-8 - --status shows hooks status, skills rendered count, agents.md freshness
 * AC: @enhanced-setup ac-9 - skills referenced by ralph (task-work, reflect) are present
 */

import * as fs from "node:fs/promises";
import { existsSync } from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import * as readline from "node:readline/promises";
import chalk from "chalk";
import type { Command } from "commander";
import {
  getGitRoot,
  getShadowStatus,
  repairShadow,
  SHADOW_BRANCH_NAME,
} from "../../parser/shadow.js";
import {
  detectAgentFromEnv,
  type AgentConfidence,
} from "../../parser/agent-detection.js";
import { errors } from "../../strings/index.js";
import { EXIT_CODES } from "../exit-codes.js";
import { error, output, success, warn } from "../output.js";

/**
 * Log a message at debug level (only when KSPEC_DEBUG=1)
 * AC: @setup-pipeline-unification ac-4
 */
function debugLog(message: string, detail?: unknown): void {
  if (process.env.KSPEC_DEBUG === "1") {
    if (detail) {
      console.error(`[DEBUG] setup: ${message}`, detail);
    } else {
      console.error(`[DEBUG] setup: ${message}`);
    }
  }
}

/**
 * Supported agent types for auto-configuration
 */
export type AgentType =
  | "claude-code"
  | "cline"
  | "roo-code"
  | "copilot-cli"
  | "gemini-cli"
  | "codex-cli"
  | "aider"
  | "opencode"
  | "amp"
  | "cursor"
  | "windsurf"
  | "unknown";

/**
 * Result of agent detection
 */
export interface DetectedAgent {
  type: AgentType;
  confidence: AgentConfidence;
  configPath?: string;
  envVars?: Record<string, string>;
}

const SETUP_AGENT_OVERRIDES = [
  "claude-code",
  "cline",
  "cursor",
  "windsurf",
  "unknown",
] as const;

type SetupAgentOverride = (typeof SETUP_AGENT_OVERRIDES)[number];

function parseSetupAgentOverride(value: string): SetupAgentOverride {
  const normalized = value.trim().toLowerCase();
  if (
    (SETUP_AGENT_OVERRIDES as readonly string[]).includes(normalized)
  ) {
    return normalized as SetupAgentOverride;
  }

  const allowed = SETUP_AGENT_OVERRIDES.join(", ");
  throw new Error(
    `Invalid --agent value "${value}". Supported values: ${allowed}`,
  );
}

function buildDetectedAgent(type: AgentType): DetectedAgent {
  if (type === "claude-code") {
    return {
      type,
      confidence: "high",
      configPath: path.join(os.homedir(), ".claude", "settings.json"),
    };
  }
  return { type, confidence: "high" };
}

/**
 * Detect which agent environment we're running in.
 * Returns the detected agent type and confidence level.
 *
 * Detection priority matters - more specific markers checked first.
 */
export function detectAgent(): DetectedAgent {
  const detected = detectAgentFromEnv();
  if (detected.type !== "unknown") {
    return detected;
  }

  // Fallback for non-interactive contexts where env markers may be absent.
  if (existsSync(path.join(os.homedir(), ".claude"))) {
    return {
      type: "claude-code",
      confidence: "low",
      configPath: path.join(os.homedir(), ".claude", "settings.json"),
    };
  }

  return detected;
}

/**
 * Install KSPEC_AUTHOR config for Claude Code (global settings)
 */
async function installClaudeCodeConfig(author: string): Promise<boolean> {
  const configPath = path.join(os.homedir(), ".claude", "settings.json");
  const configDir = path.dirname(configPath);

  try {
    // Ensure directory exists
    await fs.mkdir(configDir, { recursive: true });

    // Read existing config or start fresh
    let config: Record<string, unknown> = {};
    try {
      const existing = await fs.readFile(configPath, "utf-8");
      config = JSON.parse(existing);
    } catch (err) {
      debugLog("No existing Claude Code config, starting fresh", err);
    }

    // Merge env settings
    const env = (config.env as Record<string, string>) || {};
    env.KSPEC_AUTHOR = author;
    config.env = env;

    // Write back
    await fs.writeFile(
      configPath,
      `${JSON.stringify(config, null, 2)}\n`,
      "utf-8",
    );
    return true;
  } catch (err) {
    debugLog("Failed to install Claude Code config", err);
    return false;
  }
}

/**
 * Result of installing hooks
 * AC: @enhanced-setup ac-2 - tracks all hook types
 */
export interface HooksInstallResult {
  promptCheck: boolean;
  stop: boolean;
  preToolUse: boolean;
  guardsCreated: string[];
}

/**
 * Native guard command for PreToolUse hooks.
 * Replaces bash shell scripts with `kspec guard worktree`.
 *
 * AC: @native-guard-commands ac-setup-native - references kspec guard worktree
 */
const NATIVE_GUARD_COMMAND = "kspec guard worktree";

/**
 * Old bash script filenames that should be migrated to native commands.
 * AC: @native-guard-commands ac-migrate-hooks
 */
const OLD_GUARD_SCRIPTS = [
  "kspec-worktree-guard.sh",
  "ralph-task-limit-guard.sh",
];

/**
 * Install hooks to project-level Claude Code settings (.claude/settings.json)
 * AC: @enhanced-setup ac-2 - all hook entries present
 */
async function installClaudeCodeHooks(
  projectDir: string,
  dryRun = false,
): Promise<HooksInstallResult> {
  const configPath = path.join(projectDir, ".claude", "settings.json");
  const configDir = path.dirname(configPath);
  const hooksDir = path.join(projectDir, ".claude", "hooks");

  const result: HooksInstallResult = {
    promptCheck: false,
    stop: false,
    preToolUse: false,
    guardsCreated: [],
  };

  try {
    // Ensure directories exist
    if (!dryRun) {
      await fs.mkdir(configDir, { recursive: true });
      await fs.mkdir(hooksDir, { recursive: true });
    }

    // Read existing config or start fresh
    let config: Record<string, unknown> = {};
    try {
      const existing = await fs.readFile(configPath, "utf-8");
      config = JSON.parse(existing);
    } catch (err) {
      debugLog("No existing hooks config, starting fresh", err);
    }

    // Get or create hooks object
    const hooks = (config.hooks as Record<string, unknown[]>) || {};

    // Install UserPromptSubmit hook (spec-first reminder)
    const promptCheckCommand = "kspec session prompt-check";
    const existingPromptHooks = hooks.UserPromptSubmit as
      | Array<{ hooks?: Array<{ command?: string }> }>
      | undefined;
    const promptAlreadyInstalled = existingPromptHooks?.some((entry) =>
      entry.hooks?.some((hook) =>
        hook.command?.includes("session prompt-check"),
      ),
    );

    if (!promptAlreadyInstalled) {
      hooks.UserPromptSubmit = [
        ...(existingPromptHooks || []),
        {
          hooks: [
            {
              type: "command",
              command: promptCheckCommand,
            },
          ],
        },
      ];
      result.promptCheck = true;
    } else {
      result.promptCheck = true; // Already configured
    }

    // Install Stop hook (checkpoint)
    const stopHookCommand = "kspec session checkpoint --json";
    const existingStopHooks = hooks.Stop as
      | Array<{ matcher?: string; hooks?: Array<{ command?: string }> }>
      | undefined;
    const stopAlreadyInstalled = existingStopHooks?.some((entry) =>
      entry.hooks?.some((hook) => hook.command?.includes("session checkpoint")),
    );

    if (!stopAlreadyInstalled) {
      hooks.Stop = [
        ...(existingStopHooks || []),
        {
          matcher: "",
          hooks: [
            {
              type: "command",
              command: stopHookCommand,
            },
          ],
        },
      ];
      result.stop = true;
    } else {
      result.stop = true; // Already configured
    }

    // AC: @enhanced-setup ac-2 - Install PreToolUse hooks with guards
    // AC: @native-guard-commands ac-setup-native - use native kspec guard worktree
    // AC: @native-guard-commands ac-no-task-limit-hook - no task-limit guard
    // AC: @native-guard-commands ac-migrate-hooks - replace old bash script entries
    // AC: @native-guard-commands ac-idempotent - no duplicate entries
    const existingPreToolUseHooks = hooks.PreToolUse as
      | Array<{ matcher?: string; hooks?: Array<{ type?: string; command?: string }> }>
      | undefined;

    // Check if native guard command is already installed
    const nativeAlreadyInstalled = existingPreToolUseHooks?.some((entry) =>
      entry.hooks?.some((hook) => hook.command === NATIVE_GUARD_COMMAND),
    );

    // Check for old bash script entries that need migration
    const hasOldScripts = existingPreToolUseHooks?.some((entry) =>
      entry.hooks?.some((hook) =>
        OLD_GUARD_SCRIPTS.some(
          (name) => hook.command?.includes(name),
        ),
      ),
    );

    if (hasOldScripts || !nativeAlreadyInstalled) {
      // Remove any PreToolUse entries that reference old bash scripts
      // AC: @native-guard-commands ac-migrate-hooks
      let filteredPreToolUse = (existingPreToolUseHooks || []).map((entry) => ({
        ...entry,
        hooks: entry.hooks?.filter(
          (hook) =>
            !OLD_GUARD_SCRIPTS.some((name) => hook.command?.includes(name)),
        ),
      }));
      // Remove entries with empty hooks arrays
      filteredPreToolUse = filteredPreToolUse.filter(
        (entry) => entry.hooks && entry.hooks.length > 0,
      );

      // Add native guard command if not already present
      if (!nativeAlreadyInstalled) {
        filteredPreToolUse.push({
          matcher: "Bash",
          hooks: [
            {
              type: "command",
              command: NATIVE_GUARD_COMMAND,
            },
          ],
        });
      }

      hooks.PreToolUse = filteredPreToolUse;
      result.preToolUse = true;

      // Delete old bash script files
      // AC: @native-guard-commands ac-migrate-hooks - delete old files
      if (!dryRun) {
        for (const name of OLD_GUARD_SCRIPTS) {
          const scriptPath = path.join(hooksDir, name);
          try {
            await fs.unlink(scriptPath);
            result.guardsCreated.push(`deleted:${name}`);
          } catch (err) {
            debugLog(`Could not delete old guard script ${name}`, err);
          }
        }
      }
    } else {
      result.preToolUse = true; // Already configured with native command
    }

    config.hooks = hooks;

    // Write back
    if (!dryRun) {
      await fs.writeFile(
        configPath,
        `${JSON.stringify(config, null, 2)}\n`,
        "utf-8",
      );
    }
    return result;
  } catch (err) {
    debugLog("installClaudeCodeHooks failed", err);
    return result;
  }
}

/**
 * Install KSPEC_AUTHOR config for Aider (.aider.conf.yml)
 * Aider uses `set-env:` for environment variables in list format
 */
async function installAiderConfig(author: string): Promise<boolean> {
  const configPath = path.join(os.homedir(), ".aider.conf.yml");

  try {
    let content = "";
    try {
      content = await fs.readFile(configPath, "utf-8");
    } catch (err) {
      debugLog("No existing Aider config, starting fresh", err);
    }

    // Check if KSPEC_AUTHOR is already set
    if (content.includes("KSPEC_AUTHOR")) {
      // Replace existing value (handles both old and new format)
      content = content.replace(
        /^(\s*-?\s*KSPEC_AUTHOR\s*[=:]\s*).*$/m,
        `  - KSPEC_AUTHOR=${author}`,
      );
    } else {
      // Add to set-env section or create it
      if (content.includes("set-env:")) {
        // Append to existing set-env section
        content = content.replace(
          /(set-env:\s*\n)/m,
          `$1  - KSPEC_AUTHOR=${author}\n`,
        );
      } else {
        // Add new set-env section
        content += `\n# kspec author for note attribution\nset-env:\n  - KSPEC_AUTHOR=${author}\n`;
      }
    }

    await fs.writeFile(configPath, content, "utf-8");
    return true;
  } catch (err) {
    debugLog("installAiderConfig failed", err);
    return false;
  }
}

/**
 * Install KSPEC_AUTHOR for generic JSON config files
 */
async function installGenericJsonConfig(
  configPath: string,
  author: string,
): Promise<boolean> {
  try {
    const configDir = path.dirname(configPath);
    await fs.mkdir(configDir, { recursive: true });

    let config: Record<string, unknown> = {};
    try {
      const existing = await fs.readFile(configPath, "utf-8");
      config = JSON.parse(existing);
    } catch (err) {
      debugLog(`No existing config at ${configPath}, starting fresh`, err);
    }

    const env = (config.env as Record<string, string>) || {};
    env.KSPEC_AUTHOR = author;
    config.env = env;

    await fs.writeFile(
      configPath,
      `${JSON.stringify(config, null, 2)}\n`,
      "utf-8",
    );
    return true;
  } catch (err) {
    debugLog(`installGenericJsonConfig failed for ${configPath}`, err);
    return false;
  }
}

/**
 * Get default author value for an agent type
 */
function getDefaultAuthor(agentType: AgentType): string {
  switch (agentType) {
    case "claude-code":
      return "@claude";
    case "cline":
      return "@cline";
    case "roo-code":
      return "@roo";
    case "copilot-cli":
      return "@copilot";
    case "gemini-cli":
      return "@gemini";
    case "codex-cli":
      return "@codex";
    case "aider":
      return "@aider";
    case "opencode":
      return "@opencode";
    case "amp":
      return "@amp";
    default:
      return "@agent";
  }
}

/**
 * Prompt user for input with Y/N answer
 */
async function promptYesNo(question: string): Promise<boolean> {
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
  });

  try {
    const answer = await rl.question(`${question} `);
    return answer.toLowerCase() === "y";
  } finally {
    rl.close();
  }
}

/**
 * Ensure .kspec worktree exists if kspec-meta branch is present.
 * AC: detect-existing-repo, auto-worktree-flag, worktree-already-exists
 *
 * @param autoWorktree If true, automatically create worktree without prompting
 * @returns true if worktree is ready to use
 */
async function ensureWorktree(autoWorktree: boolean): Promise<boolean> {
  const projectRoot = getGitRoot(process.cwd());
  if (!projectRoot) {
    // Not in a git repo, skip worktree check
    return true;
  }

  const status = await getShadowStatus(projectRoot);

  // AC: worktree-already-exists - if already valid, skip
  if (status.healthy) {
    return true;
  }

  // AC: detect-existing-repo - branch exists but worktree doesn't
  if (status.branchExists && !status.worktreeExists) {
    // AC: auto-worktree-flag - auto-create if flag set
    if (autoWorktree) {
      console.log(
        `Detected ${SHADOW_BRANCH_NAME} branch without .kspec worktree. Creating...`,
      );
      const result = await repairShadow(projectRoot);
      if (result.success) {
        success("Created .kspec worktree");
        return true;
      } else {
        error(`Failed to create worktree: ${result.error}`);
        return false;
      }
    }

    // AC: detect-existing-repo - prompt user
    const shouldCreate = await promptYesNo(
      `${SHADOW_BRANCH_NAME} branch exists but .kspec worktree is missing. Create it? (y/N)`,
    );

    if (shouldCreate) {
      console.log("Creating .kspec worktree...");
      const result = await repairShadow(projectRoot);
      if (result.success) {
        success("Created .kspec worktree");
        return true;
      } else {
        error(`Failed to create worktree: ${result.error}`);
        return false;
      }
    } else {
      warn("Skipping worktree creation");
      return false;
    }
  }

  // No kspec-meta branch, or already healthy
  return true;
}

