1856→        // AC: detect-existing-repo, auto-worktree-flag, worktree-already-exists
1857→        const worktreeReady = await ensureWorktree(
1858→          options.autoWorktree || false,
1859→        );
1860→        if (!worktreeReady) {
1861→          // User declined worktree creation or it failed
1862→          process.exit(EXIT_CODES.ERROR);
1863→        }
1864→
1865→        const detected = agentOverride
1866→          ? buildDetectedAgent(agentOverride)
