1895→              status: s.status,
1896→              message: s.message,
1897→              details: s.details,
1898→            })),
1899→          },
1900→          () => {
1901→            if (dryRun) {
1902→              console.log(chalk.yellow("DRY RUN - No changes made\n"));
1903→            }
1904→
1905→            // Pipeline already prints the summary when not dry-run
1906→            // For dry-run, print it here since the pipeline skips output
1907→            if (dryRun) {
1908→              console.log(chalk.bold("kspec Setup Summary\n"));
1909→
1910→              for (const step of result.steps) {
1911→                const icon =
1912→                  step.status === "done"
1913→                    ? chalk.green("✓")
1914→                    : step.status === "skipped"
1915→                      ? chalk.gray("○")
1916→                      : chalk.red("✗");
1917→                const statusText =
1918→                  step.status === "done"
1919→                    ? ""
1920→                    : step.status === "skipped"
1921→                      ? chalk.gray(" (skipped)")
1922→                      : chalk.red(" (failed)");
1923→
1924→                console.log(`${icon} ${step.name}${statusText}`);
1925→                if (step.message) {
1926→                  console.log(chalk.gray(`  ${step.message}`));
1927→                }
1928→              }
1929→            }
1930→
1931→            console.log();
1932→
1933→            if (dryRun) {
1934→              console.log(
1935→                chalk.yellow("Run without --dry-run to apply changes."),
1936→              );
1937→            } else {
1938→              console.log(
1939→                chalk.green("Setup complete."),
1940→              );
1941→              console.log(
1942→                chalk.gray("Restart your agent session for changes to take effect."),
1943→              );
1944→            }
1945→          },
1946→        );
1947→      } catch (err) {
1948→        error(errors.failures.setupFailed, err);
1949→        process.exit(EXIT_CODES.ERROR);
1950→      }
1951→    });
