    13→ * AC Coverage:
    14→ * - @daemon-agent-dispatch ac-2: CLI posts state change event to POST /api/agent/events
    15→ * - @daemon-agent-dispatch ac-3, ac-4: WebSocket broadcast on invocation start/complete/fail
    16→ * - @daemon-agent-dispatch ac-5: GET /api/agent/status returns public status shape
    17→ * - @daemon-agent-dispatch ac-6: POST /api/agent/dispatch with action start|stop
    18→ * - @daemon-agent-dispatch ac-7: Event emission fails silently when engine not running
    19→ * - @agent-dispatch-engine ac-4: CLI posts state change event to daemon
    20→ */
    21→
    22→import { Elysia, t } from 'elysia';
    23→import { DispatchEngine } from '../../agent-runtime/dispatch.js';
    24→import type { TaskStateChange, TaskStatus, InvocationEvent } from '../../agent-runtime/dispatch.js';
    25→import { DEFAULT_KSPEC_CLI_PATH } from '../../agent-runtime/invocation.js';
    26→import { initContext, loadMetaContext } from '../../parser/index.js';
    27→import { getCompletedSessionCountsByAgent } from '../../sessions/store.js';
    28→import type { PubSubManager } from '../websocket/pubsub.js';
    29→
    30→const VALID_TASK_STATUSES = new Set<string>([
    31→  "pending", "in_progress", "pending_review", "needs_work", "blocked", "completed", "cancelled",
    32→]);
    33→
    34→// Singleton dispatch engine per project path
    35→const engines: Map<string, DispatchEngine> = new Map();
    36→
    37→export interface AgentDispatchRouteOptions {
    38→  defaultProjectPath?: string;
    39→  /** PubSubManager for broadcasting agent invocation events to WebSocket clients */
    40→  pubsub?: PubSubManager;
    41→}
    42→
    43→/**
    44→ * Create a new dispatch engine with optional WebSocket broadcast wiring.
    45→ * AC: @daemon-agent-dispatch ac-3, ac-4
    46→ */
    47→function createEngine(projectDir: string, pubsub?: PubSubManager): DispatchEngine {
    48→  return new DispatchEngine({
    49→    projectDir,
    50→    kspecCliPath: DEFAULT_KSPEC_CLI_PATH,
    51→    onInvocationEvent: pubsub
    52→      ? (event: InvocationEvent) => {
    53→          pubsub.broadcast('agents', 'agent_invocation', {
    54→            session_id: event.session_id,
    55→            agent_id: event.agent_id,
    56→            task_id: event.task_id ?? null,
    57→            status: event.status,
    58→            timestamp: event.timestamp,
    59→          }, projectDir);
    60→        }
    61→      : undefined,
    62→    // AC: @cli-agent-commands ac-13, @daemon-agent-dispatch ac-8
    63→    onTextChunk: pubsub
    64→      ? (sessionId: string, agentId: string, taskId: string | null, text: string) => {
    65→          pubsub.broadcast('agents', 'agent_text_chunk', {
    66→            session_id: sessionId,
    67→            agent_id: agentId,
    68→            task_id: taskId,
    69→            text,
    70→            timestamp: Date.now(),
    71→          }, projectDir);
    72→        }
    73→      : undefined,
    74→  });
    75→}
    76→
    77→const stateChangeBodySchema = t.Object({
    78→  task_id: t.String(),
    79→  task_ref: t.Optional(t.String()),
    80→  from_status: t.String(),
    81→  to_status: t.String(),
    82→  timestamp: t.Optional(t.Number()),
    83→});
    84→
    85→type StateChangeBody = {
    86→  task_id: string;
    87→  task_ref?: string;
    88→  from_status: string;
    89→  to_status: string;
    90→  timestamp?: number;
    91→};
    92→
    93→function processStateChangeEvent(
    94→  engine: DispatchEngine | undefined,
    95→  body: StateChangeBody,
    96→): { accepted: boolean; reason?: string } {
    97→  if (!engine || !engine.getStatus().running) {
    98→    return { accepted: false, reason: 'Dispatch engine not running' };
    99→  }
   100→
   101→  if (!VALID_TASK_STATUSES.has(body.from_status) || !VALID_TASK_STATUSES.has(body.to_status)) {
   102→    return { accepted: false, reason: `Invalid status: from_status="${body.from_status}" to_status="${body.to_status}". Valid values: ${[...VALID_TASK_STATUSES].join(", ")}` };
   103→  }
   104→
   105→  const change: TaskStateChange = {
   106→    taskId: body.task_id,
   107→    taskRef: body.task_ref ?? `@${body.task_id}`,
   108→    fromStatus: body.from_status as TaskStatus,
   109→    toStatus: body.to_status as TaskStatus,
   110→    timestamp: body.timestamp ?? Date.now(),
   111→  };
   112→
   113→  engine.handleStateChange(change).catch((err) => {
   114→    console.error('[dispatch] Error handling state change event:', err);
   115→  });
   116→
   117→  return { accepted: true };
   118→}
   119→
   120→export function createAgentDispatchRoutes(options: AgentDispatchRouteOptions = {}) {
   121→  const { pubsub } = options;
   122→
   123→  return new Elysia({ prefix: '/api/agent' })
   124→
   125→    // AC: @daemon-agent-dispatch ac-2, ac-7 - CLI posts state change event to daemon
   126→    // AC: @agent-dispatch-engine ac-4
   127→    .post('/events', ({ body, projectContext }) => {
   128→      return processStateChangeEvent(engines.get(projectContext.path), body);
   129→    }, { body: stateChangeBodySchema })
   130→
   131→    // Legacy alias — same as /events
   132→    .post('/event', ({ body, projectContext }) => {
   133→      return processStateChangeEvent(engines.get(projectContext.path), body);
   134→    }, { body: stateChangeBodySchema })
   135→
   136→    // AC: @daemon-agent-dispatch ac-6 - Unified dispatch start/stop via action field
   137→    .post('/dispatch', async ({ body, projectContext }) => {
   138→      const projectDir = projectContext.path;
   139→
   140→      if (body.action === 'start') {
   141→        let engine = engines.get(projectDir);
   142→        if (engine?.getStatus().running) {
   143→          return { dispatch_enabled: true, reason: 'Already running' };
   144→        }
   145→
   146→        engine = createEngine(projectDir, pubsub);
   147→        engines.set(projectDir, engine);
   148→        await engine.start();
   149→
   150→        return { dispatch_enabled: true };
   151→      } else {
   152→        const engine = engines.get(projectDir);
   153→        if (!engine) {
   154→          return { dispatch_enabled: false, reason: 'No engine running' };
   155→        }
   156→
   157→        await engine.stop();
   158→        engines.delete(projectDir);
   159→
   160→        return { dispatch_enabled: false };
   161→      }
   162→    }, {
   163→      body: t.Object({
   164→        action: t.Union([t.Literal('start'), t.Literal('stop')]),
   165→      }),
   166→    })
   167→
   168→    // Start dispatch engine (legacy route)
   169→    .post('/dispatch/start', async ({ projectContext }) => {
   170→      const projectDir = projectContext.path;
   171→
   172→      let engine = engines.get(projectDir);
   173→      if (engine?.getStatus().running) {
   174→        return { started: false, reason: 'Already running', status: engine.getStatus() };
   175→      }
   176→
   177→      // AC: @agent-dispatch-engine ac-10 - pass kspecCliPath so task notes work from daemon-started engine
   178→      engine = createEngine(projectDir, pubsub);
   179→      engines.set(projectDir, engine);
   180→
   181→      await engine.start();
   182→
   183→      return { started: true, status: engine.getStatus() };
   184→    })
   185→
   186→    // Stop dispatch engine (legacy route)
   187→    .post('/dispatch/stop', async ({ projectContext }) => {
   188→      const projectDir = projectContext.path;
   189→      const engine = engines.get(projectDir);
   190→
   191→      if (!engine) {
   192→        return { stopped: false, reason: 'No engine running' };
   193→      }
   194→
   195→      await engine.stop();
   196→      engines.delete(projectDir);
   197→
   198→      return { stopped: true };
   199→    })
   200→
   201→    // Get dispatch engine status (internal format)
   202→    .get('/dispatch/status', ({ projectContext }) => {
   203→      const engine = engines.get(projectContext.path);
   204→
   205→      if (!engine) {
   206→        return {
   207→          running: false,
   208→          activeInvocations: 0,
   209→          queuedInvocations: 0,
   210→          invocations: [],
   211→        };
   212→      }
   213→
   214→      return engine.getStatus();
   215→    })
   216→
   217→    // AC: @daemon-agent-dispatch ac-5 - Public status endpoint
   218→    .get('/status', async ({ projectContext }) => {
   219→      const projectDir = projectContext.path;
   220→      const engineStatus = engines.get(projectDir)?.getStatus();
   221→
   222→      let agentDefinitions: Array<{ id: string; name: string; adapter: string; completed_sessions: number }> = [];
   223→      let completedCounts: Record<string, number> = {};
   224→      try {
   225→        const ctx = await initContext(projectDir);
   226→        const [meta, counts] = await Promise.all([
   227→          loadMetaContext(ctx),
   228→          getCompletedSessionCountsByAgent(ctx.specDir),
   229→        ]);
   230→        completedCounts = counts;
   231→        agentDefinitions = meta.agents.map((a) => ({
   232→          id: a.id,
   233→          name: a.name,
   234→          adapter: a.adapter ?? 'claude-agent-acp',
   235→          completed_sessions: completedCounts[a.id] ?? 0,
   236→        }));
   237→      } catch {
   238→        // Agent definitions unavailable — return empty array
   239→      }
   240→
   241→      return {
   242→        dispatch_enabled: engineStatus?.running ?? false,
   243→        active_invocations: engineStatus?.invocations?.map((inv) => ({
   244→          session_id: inv.sessionId,
   245→          agent_id: inv.agentId,
   246→          task_ref: inv.taskRef ?? null,
   247→          elapsed_ms: inv.elapsedMs,
   248→        })) ?? [],
   249→        queue_depth: engineStatus?.queuedInvocations ?? 0,
   250→        agent_definitions: agentDefinitions,
   251→      };
   252→    });
   253→}
   254→
   255→/**
   256→ * Get the dispatch engine for a project path (for integration with file watcher).
   257→ */
   258→export function getDispatchEngine(projectDir: string): DispatchEngine | undefined {
   259→  return engines.get(projectDir);
   260→}
   261→
   262→/**
   263→ * Stop all active dispatch engines. Called on daemon shutdown.
   264→ * AC: @agent-dispatch-engine ac-11 - daemon shutdown stops active engines
   265→ */
   266→export async function stopAllEngines(): Promise<void> {
   267→  const stopPromises: Promise<void>[] = [];
   268→  for (const [projectDir, engine] of engines) {
   269→    console.log(`[dispatch] Stopping engine for ${projectDir}...`);
   270→    stopPromises.push(
   271→      engine.stop().catch((err) => {
   272→        console.error(`[dispatch] Error stopping engine for ${projectDir}:`, err);
   273→      })
   274→    );
   275→  }
   276→  await Promise.all(stopPromises);
   277→  engines.clear();
   278→  console.log('[dispatch] All engines stopped');
   279→}
   280→
